const body = $json.body?.message ?? $json.body ?? {};

const vapiCallId = body.call?.id ?? null;
const summary = body.summary ?? body.analysis?.summary ?? null;
const transcript = body.transcript ?? '';
const durationSeconds = Math.round(body.durationSeconds ?? 0);
const endedReason = body.endedReason ?? 'unknown';
const startedAt = body.startedAt ?? null;
const endedAt = body.endedAt ?? null;
const cost = body.cost ?? 0;
const recordingUrl = body.recordingUrl ?? null;
const successEval = body.analysis?.successEvaluation ?? null;

const metadata = body.call?.assistantOverrides?.metadata ?? body.assistant?.metadata ?? {};
const echoSoulUserId = metadata.echosoul_user_id ?? null;
const echoSoulCallRecordId = metadata.echosoul_call_record_id ?? null;

return [{
  json: {
    vapi_call_id: vapiCallId,
    echosoul_user_id: echoSoulUserId,
    echosoul_call_record_id: echoSoulCallRecordId,
    summary,
    transcript,
    duration_seconds: durationSeconds,
    ended_reason: endedReason,
    started_at: startedAt,
    ended_at: endedAt,
    cost,
    recording_url: recordingUrl,
    success_evaluation: successEval,
    has_meaningful_transcript: transcript.length > 50
  }
}];

